fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // If keepends is true, use split_inclusive to keep trailing '\n'
            // Otherwise, use lines() which drops line endings.
            let lines_iter: Box<dyn Iterator<Item = &str>> = if keepends {
                Box::new(s.split_inclusive('\n'))
            } else {
                Box::new(s.lines())
            };

            // Collect lines into a Vec<String>
            let lines_vec: Vec<String> = lines_iter.map(|line| line.to_string()).collect();

            // Since lines() on empty string returns empty iterator,
            // ensure inner vec is non-empty by adding "" if empty
            if lines_vec.is_empty() {
                vec![String::new()]
            } else {
                lines_vec
            }
        })
        .collect()
}